    (TValue q2, rem) = TValue.DivRem((rem * baseValue) + (high & lowMask), divisor);
    (TValue q1, rem) = TValue.DivRem((rem * baseValue) + (low >> half), divisor);
    (TValue q0, rem) = TValue.DivRem((rem * baseValue) + (low & lowMask), divisor);

    high = (q3 << half) | q2;
    low = (q1 << half) | q0;
    return rem;
}
